// Turns what the book says about an NPC into short, playable roleplay notes.
// Text only, chosen from fixed lists: nothing is generated by a model, no voices or pictures.

const TRAITS = [
  [/\b(stern|strict|severe|streng)\b/i, 'Short, flat sentences. Never says please.', 'Taps the table while others talk.'],
  [/\b(tired|weary|exhausted|müde)\b/i, 'Sighs before answering and repeats questions back.', 'Rubs their eyes and leans on things.'],
  [/\b(nervous|anxious|panic|scared|frightened|afraid|nervös|ängstlich)\b/i, 'Talks too fast and trails off mid-sentence.', 'Fidgets with something small and avoids eye contact.'],
  [/\b(cheerful|jolly|happy|merry|fröhlich)\b/i, 'Warm and sing-song; laughs at their own jokes.', 'Leans in close and touches people\'s arms.'],
  [/(?<![-\w])(old|elderly|ancient|alt|greis)\b/i, 'Slow, with long pauses to remember names.', 'Squints and lowers themself into chairs carefully.'],
  [/\b(young|youthful|child|boy|girl|jung)\b/i, 'Eager; interrupts and asks questions back.', 'Can\'t stand still.'],
  [/\b(gruff|grumpy|surly|mürrisch)\b/i, 'Grunts and gives one-word answers until impressed.', 'Arms crossed, chin up.'],
  [/\b(greedy|merchant|haggl|gierig|händler)\b/i, 'Steers every topic back to money.', 'Weighs coins in their hand while talking.'],
  [/\b(suspicious|paranoid|wary|misstrauisch)\b/i, 'Answers questions with questions.', 'Watches the door; keeps a hand near a weapon.'],
  [/\b(kind|gentle|caring|freundlich|gütig)\b/i, 'Soft voice; uses the party\'s names.', 'Offers food or a seat before anything else.'],
  [/\b(proud|arrogant|haughty|noble|stolz|arrogant)\b/i, 'Formal words; corrects other people\'s mistakes.', 'Straight back; never sits first.'],
  [/\b(drunk|drunken|betrunken)\b/i, 'Slurred, overly honest, wanders off topic.', 'Sways and spills things.'],
  [/\b(cruel|sadistic|vicious|grausam)\b/i, 'Quiet and amused at other people\'s pain.', 'Smiles at the wrong moments.'],
  [/\b(riddles?|cryptic|rätsel)\b/i, 'Answers in riddles and half-truths.', 'Hums between sentences.'],
  [/\b(clown|jester|joke|prank)\b/i, 'Turns every answer into a joke or a rhyme.', 'Big theatrical gestures; bows after speaking.'],
  [/\b(priest|cleric|acolyte|pious|faith|priester)\b/i, 'Quotes scripture or sayings of their god.', 'Touches a holy symbol when worried.'],
  [/\b(soldier|guard|captain|veteran|soldat|wache)\b/i, 'Clipped and military; calls people by rank or "you".', 'Stands at attention; scans the room.'],
  [/\b(scholar|sage|wizard|mage|professor|gelehrt)\b/i, 'Long words, then explains them unasked.', 'Pushes up spectacles; scribbles notes.'],
  [/\b(hag|witch|crone|hexe)\b/i, 'Sweet as honey until crossed, then cold.', 'Cackles softly; strokes a pet or trinket.'],
  [/\b(thief|rogue|smuggler|spy|dieb|schmuggler)\b/i, 'Low voice; never gives a straight answer.', 'Keeps glancing at exits and pockets.'],
  [/\b(confident|bold|brash|swagger)\b/i, 'Loud and sure; talks over people.', 'Takes up space; feet on the table.'],
  [/\b(sad|grieving|mourning|lost|traurig)\b/i, 'Quiet; drifts into memories mid-sentence.', 'Holds a keepsake tightly.']
];

const pick = (text, idx) => { for (const t of TRAITS) if (t[0].test(text)) return t[idx]; return null; };

export function roleplayTips(npc) {
  const f = npc.fields || {};
  const about = [npc.role, npc.desc, f.appearance, f.does, f.personality, f.mannerisms, f.aussehen, f.auftreten].filter(Boolean).join(' ');
  const voice = f.voice || pick(about, 1) || 'Borrow how someone you know talks, and keep it the same each time.';
  // second trait for the gesture, so voice and gesture don't come from the same line
  let manner = f.does || f.mannerisms || f.auftreten || null;
  if (!manner) { const hits = TRAITS.filter(t => t[0].test(about)); manner = (hits[1] || hits[0] || [])[2] || 'Give them one repeated gesture the players will remember.'; }
  const secret = f.secret || f.geheimnis || '';
  return {
    voice, manner,
    look: f.appearance || f.aussehen || '',
    wants: f.wants || '',
    secret,
    knows: f.knows || '',
    line: (npc.quotes && npc.quotes[0]) || '',
    pressed: secret ? 'Lies at first. Gives the secret up if shown proof, threatened, or offered a way out.' : 'Has nothing to hide, but wants something in return for help.'
  };
}
